CUES = [
 (0, 1, S, "", "Hadis ketujuh:", ""),
 (2, 18, H, "عنْ تَميمٍ الدَّاريّ رضي الله عنه أنَّ النَّبيَّ ﷺ قال:",
  "Daripada Tamim bin Aus ad-Dari رضي الله عنه, sesungguhnya Nabi ﷺ bersabda:", ""),
 (19, 24, H, "«الدِّينُ النَّصيحَةُ» ثلاثًا",
  "“Agama itu adalah nasihat.” Baginda mengulanginya tiga kali.", ""),
 (25, 26, H, "قُلْنا: لِمَنْ يا رَسُولَ اللهِ؟", "Kami bertanya: “Untuk siapa?”", ""),
 (27, 33, H, "قالَ: «للهِ ولِكتابِهِ ولِرَسولِهِ ولأئمَّةِ المُسلِمِينَ وعامَّتِهم»",
  "Sabda Nabi ﷺ: “Untuk Allah, untuk kitab-Nya, untuk rasul-Nya, dan untuk para pemimpin Muslimin dan umat Muslim seluruhnya.”", "Riwayat Muslim — Hadis 40, no. 7"),
 (34, 38, S, "", "Diriwayatkan oleh Imam Muslim dalam Sahihnya.", ""),
 (39, 47, S, "", "Tamim ad-Dari ialah Tamim bin Aus ad-Dari, Abu Ruqayyah.", ""),
 (48, 55, S, "", "Beliau memeluk Islam pada tahun kesembilan Hijrah, dan kisahnya masyhur —", ""),
 (56, 61, S, "", "ketika beliau keluar ke laut lalu melihat Dajjal.", ""),
 (62, 73, S, "", "Beliau termasuk sahabat Nabi ﷺ yang kuat beribadah, walaupun lewat memeluk Islam.", ""),
 (74, 78, S, "", "Beliau wafat pada tahun 40 Hijrah.", ""),
 (79, 86, H, NASIHAH, "Sabda Nabi ﷺ: “Agama itu adalah nasihat.”", ""),
 (87, 98, S, "", "Nasihat itu daripada kata an-nush. Dikatakan “nashaha al-‘asal” apabila madu ditulenkan dan dibuang kekotorannya.", ""),
 (99, 104, S, "", "Yang dimaksudkan di sini ialah menasihati kaum Muslimin secara umum.", ""),
 (105, 112, S, "", "Daripada Jarir bin Abdullah al-Bajali, beliau berkata:", ""),
 (113, 127, H, "«بَايَعْتُ النَّبِيَّ ﷺ عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ»",
  "“Aku berbaiah dengan Nabi ﷺ untuk mendirikan solat, menunaikan zakat dan menasihati setiap Muslim.”", ""),
 (128, 140, S, "", "Hadis ini ada kisahnya, iaitu Jarir bin Abdullah رضي الله عنه", ""),
 (141, 154, S, "", "apabila membeli seekor kuda dengan harga yang lebih rendah daripada nilainya, beliau memanggil pemilik kuda itu dan memberinya dua kali ganda harganya,", ""),
 (155, 166, S, "", "lalu berkata: “Aku berbaiah dengan Rasulullah ﷺ untuk menasihati setiap Muslim.”", ""),
 (167, 178, S, "", "Dan ini hampir tidak dilakukan oleh sesiapa pun pada hari ini, kecuali orang yang dirahmati Allah Tabaraka wa Ta‘ala.", ""),
 (179, 188, S, "", "Nabi ﷺ bersabda: nasihat itu untuk Allah — ketika baginda ditanya:", ""),
 (189, 197, H, "النَّصِيحَةُ لِمَنْ؟ قَالَ: «لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ»",
  "“Nasihat untuk siapa?” Baginda bersabda: “Untuk Allah, untuk kitab-Nya, untuk rasul-Nya, dan untuk para pemimpin Muslimin dan umat Muslim seluruhnya.”", ""),
 (198, 203, S, "", "Nasihat kepada para pemimpin urusan, dan nasihat para pemimpin kepada rakyat mereka.", ""),
 (204, 211, S, "", "Pemimpin urusan, anda menasihatinya, begitu juga dia menasihati anda.", ""),
 (212, 218, S, "", "Dalam hal ini ada sabda Nabi ﷺ:", ""),
 (219, 232, H, "«مَا مِنْ عَبْدٍ يَسْتَرْعِيهِ اللهُ رَعِيَّةً ثُمَّ لَمْ يَحُطْهَا بِنُصْحِهِ إِلَّا لَمْ يَدْخُلِ الْجَنَّةَ»",
  "“Tiada seorang hamba yang Allah amanahkan kepadanya rakyat, kemudian dia tidak menjaga mereka dengan nasihatnya, melainkan dia tidak akan masuk syurga.”", ""),
 (233, 239, S, "", "Dikeluarkan oleh al-Bukhari dan Muslim dalam kedua-dua Sahih mereka.", ""),
 (240, 242, S, "", "Ada juga nasihat kepada golongan lemah.", ""),
 (243, 251, S, "", "Golongan lemah ialah mereka yang tidak memiliki apa yang boleh dibelanjakan.", ""),
 (252, 253, S, "", "Allah Ta‘ala berfirman:", ""),
 (254, 277, Q, "لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ",
  "“Orang-orang yang lemah dan orang-orang yang sakit, dan juga orang-orang yang tidak mempunyai sesuatu yang akan dibelanjakan, tidaklah menanggung dosa (kerana tidak turut berperang) apabila mereka berlaku ikhlas kepada Allah dan RasulNya.”", "Surah at-Taubah, 9:91"),
 (278, 298, S, "", "Jauh sekali bezanya antara mereka dengan orang yang ketinggalan daripada Rasulullah ﷺ atau daripada kaum Muslimin dalam jihad mereka, tanpa memberi nasihat kepada mereka.", ""),
 (299, 310, S, "", "Dikatakan “nashahahu” dan “nashaha lahu”; yang lebih masyhur dan lebih tepat ialah “nashaha lahu”, bukan “nashahahu”.", ""),
 (311, 321, S, "", "Maksudnya dia menginginkan kebaikan untuknya. Nasihat, seperti yang dikatakan, ialah menginginkan kebaikan untuk orang lain.", ""),
 (322, 333, S, "", "Nasihat ialah menginginkan kebaikan untuk orang lain — dia mahukan kebaikan bagi orang lain. Inilah nasihat.", ""),
 (334, 343, H, NASIHAH, "Apabila Nabi ﷺ bersabda: “Agama itu adalah nasihat,”", ""),
 (344, 349, S, "", "maksudnya tiang agama dan asasnya ialah nasihat.", ""),
 (350, 356, S, "", "Maksudnya, perkataan ini — apabila baginda bersabda “Agama itu adalah nasihat” —", ""),
 (357, 365, H, "«الْحَجُّ عَرَفَةُ»", "sama seperti sabda Nabi ﷺ: “Haji itu Arafah.”", ""),
 (366, 380, S, "", "Apabila orang Arab berkata, “Manusia itu Bani Tamim,” mereka maksudkan inilah yang paling penting atau paling besar.", ""),
 (381, 389, H, NASIHAH, "Maka apabila Nabi ﷺ bersabda: “Agama itu adalah nasihat,”", ""),
 (390, 402, S, "", "maksudnya tiang agama dan tonggak agama ini bersandar pada perkara yang agung ini, iaitu nasihat.", ""),
 (403, 411, S, "", "Ia juga termasuk dalam sabda Nabi ﷺ:", ""),
 (412, 420, H, LA_YU2MIN, LA_YU2MIN_MS, ""),
 (421, 435, S, "", "Nasihat bermaksud menginginkan kebaikan untuk orang lain. Ringkasnya, nasihat ialah menginginkan kebaikan untuk orang lain.", ""),
 (436, 446, S, "", "Ia wajib mengikut keperluan dan kemampuan, dan ia termasuk fardu kifayah.", ""),
 (447, 457, S, "", "Nasihat untuk Allah. Kata ulama: nasihat untuk Allah ialah mengikhlaskan ibadah kepada-Nya,", ""),
 (458, 469, S, "", "membenarkan khabar-Nya, bersaksi bagi-Nya dengan keesaan, membela agama-Nya, menunaikan perintah-Nya dan menjauhi larangan-Nya.", ""),
 (470, 480, S, "", "Inilah nasihat untuk Allah. Apabila disebut “nasihat untuk Allah”, inilah maksudnya.", ""),
 (481, 490, S, "", "Adapun nasihat untuk Kitab ialah memahaminya, mentadabburnya, menunaikan perintahnya, menjauhi larangannya,", ""),
 (491, 503, S, "", "membacanya, menghafalnya, menyebarkannya dan mengajarkannya. Semua ini termasuk nasihat untuk Kitab Allah Tabaraka wa Ta‘ala.", ""),
 (504, 514, S, "", "Adapun nasihat untuk Rasulullah ﷺ ialah memurnikan ikutan kepada baginda,", ""),
 (515, 526, S, "", "iaitu tidak mendahulukan kata-kata sesiapa pun atas kata-kata Rasulullah ﷺ,", ""),
 (527, 539, S, "", "menunaikan perintahnya, menjauhi larangannya, beriman bahawa baginda rasul daripada sisi Allah Tabaraka wa Ta‘ala,", ""),
 (540, 545, S, "", "membelanya — selawat dan salam Tuhanku ke atasnya — dan mencintainya,", ""),
 (546, 557, S, "", "dan tambahlah apa sahaja yang anda mahu daripada nasihat untuk Rasulullah ﷺ.", ""),
 (558, 568, S, "", "Nasihat untuk sunnah Nabi ﷺ ialah dengan membelanya, menulisnya, menghafalnya, menerangkannya,", ""),
 (569, 581, S, "", "membezakan hadis sahih daripada yang daif, menerangkan keadaan para perawi — iaitu perawi hadis — dan menerangkan ‘illah (kecacatan tersembunyi),", ""),
 (582, 591, S, "", "dan selain itu daripada nasihat untuk sunnah Nabi ﷺ.", ""),
 (592, 599, S, "", "Adapun nasihat untuk para imam kaum Muslimin, maka imam kaum Muslimin di sini", ""),
 (600, 607, S, "", "kadang-kadang para ulama, kadang-kadang para pemerintah.", ""),
 (608, 616, S, "", "Jika disebut secara mutlak, yang dimaksudkan ialah para pemerintah, iaitu pemegang urusan kaum Muslimin,", ""),
 (617, 622, S, "", "tetapi para ulama juga dinamakan demikian.", ""),
 (623, 627, S, "", "Antaranya firman Allah Tabaraka wa Ta‘ala:", ""),
 (628, 639, Q, "وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ",
  "“…kalau mereka kembalikan sahaja hal itu kepada Rasulullah dan kepada ‘Ulil-Amri’ (orang-orang yang berkuasa) di antara mereka, tentulah hal itu dapat diketahui oleh orang-orang yang layak mengambil keputusan mengenainya di antara mereka…”", "Surah an-Nisa’, 4:83"),
 (640, 647, S, "", "Mereka itulah para ulama. Dan firman Allah Tabaraka wa Ta‘ala:", ""),
 (648, 658, Q, "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ",
  "“Wahai orang-orang yang beriman, taatlah kamu kepada Allah dan taatlah kamu kepada Rasulullah dan kepada ‘Ulil-Amri’ (orang-orang yang berkuasa) dari kalangan kamu…”", "Surah an-Nisa’, 4:59"),
 (659, 666, S, "", "Ada yang berpendapat mereka ulama, ada yang berpendapat mereka pemerintah.", ""),
 (667, 680, S, "", "Kedua-dua makna itu berkemungkinan, walaupun makna pemerintah lebih kuat daripada makna ulama dalam ayat ini.", ""),
 (681, 689, S, "", "Walau bagaimanapun, sabda Nabi ﷺ", ""),
 (690, 700, H, "النَّصِيحَةُ لِمَنْ؟ قَالَ: «لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ»",
  "ketika ditanya, “Nasihat untuk siapa?”, baginda bersabda: “Untuk Allah, untuk kitab-Nya, untuk rasul-Nya dan untuk para pemimpin Muslimin.”", ""),
 (701, 706, S, "", "Yang masyhur, yang dimaksudkan dengan para imam kaum Muslimin ialah", ""),
 (707, 715, S, "", "pemegang urusan: sultan, raja, imam, ulil amri, amirul mukminin —", ""),
 (716, 722, S, "", "namakanlah apa sahaja yang anda mahu — maka wajib menasihatinya.", ""),
 (723, 737, S, "", "Termasuk dalam hal ini, seperti yang kita katakan, para ulama: dengan mencintai mereka, membela mereka, membantu mazhab mereka dan perkara lain,", ""),
 (738, 742, S, "", "beradab dengan mereka dan membantu mereka.", ""),
 (743, 747, S, "", "Adapun para pemegang urusan, nasihat kepada mereka ialah:", ""),
 (748, 752, S, "", "mengakui kepimpinan, mentaati dan menutup keaiban mereka,", ""),
 (753, 759, S, "", "tidak memberontak terhadap mereka, berjihad bersama mereka, solat di belakang mereka,", ""),
 (760, 770, S, "", "menunaikan zakat kepada mereka, mentaati mereka dalam perkara makruf. Semua ini termasuk nasihat kepada pemegang urusan.", ""),
 (771, 781, S, "", "Adapun nasihat kepada orang awam Muslimin, ialah dia menyukai bagi saudaranya apa yang dia sukai bagi dirinya,", ""),
 (782, 787, S, "", "menyayangi yang kecil, menghormati yang tua,", ""),
 (788, 793, S, "", "berkongsi kegembiraan mereka dan berkongsi kesedihan mereka.", ""),
 (794, 799, S, "", "Semua ini termasuk nasihat kepada orang awam Muslimin.", ""),
 (800, 809, S, "", "Ibn al-Mubarak berkata ketika ditanya amalan manakah yang paling afdal, beliau menjawab:", ""),
 (810, 816, S, "", "“Nasihat untuk Allah.” Inilah amalan yang paling afdal — nasihat untuk Allah.", ""),
 (817, 828, S, "", "Al-Fudhail bin ‘Iyadh berkata: Orang yang mencapai (kedudukan) di sisi kami bukan kerana banyak solat dan puasa,", ""),
 (829, 837, S, "", "tetapi dia mencapainya di sisi kami dengan kemurahan jiwa, kebersihan dada, dan nasihat untuk umat.", ""),
 (838, 845, S, "", "Nasihat untuk umat ini tidak mampu dilakukan oleh sesiapa sahaja,", ""),
 (846, 854, S, "", "hanya golongan khusus yang dipilih Allah berdasarkan ilmu, Maha Suci dan Maha Tinggi Dia,", ""),
 (855, 862, S, "", "lalu mereka mencapai darjat yang agung ini di sisi Allah Tabaraka wa Ta‘ala.", ""),
 (863, 881, S, "", "Abu Bakr al-Muzani berkata: Abu Bakr as-Siddiq tidak mengatasi para sahabat Rasulullah ﷺ dengan puasa dan tidak pula dengan solat.", ""),
 (882, 891, S, "", "Ada sahabat yang berpuasa lebih banyak daripada Abu Bakr,", ""),
 (892, 904, S, "", "ada sahabat yang lebih banyak beribadah dan bersolat berbanding Abu Bakr, seperti Abu ad-Darda’, misalnya.", ""),
 (905, 910, S, "", "Abu ad-Darda’ bersolat sepanjang malam,", ""),
 (911, 920, S, "", "Abdullah bin ‘Amr bin al-‘As bersolat sepanjang malam,", ""),
 (921, 929, S, "", "Abdullah bin ‘Amr bin al-‘As berpuasa sepanjang masa.", ""),
 (930, 944, S, "", "Maka Abu Bakr al-Muzani berkata, solat Abu Bakr as-Siddiq tidak lebih banyak daripada solat para sahabat yang lain,", ""),
 (945, 951, S, "", "dan puasanya tidak lebih banyak daripada sahabat lain,", ""),
 (952, 960, S, "", "tetapi kerana sesuatu yang ada di dalam hatinya — sesuatu yang ada di dalam hatinya.", ""),
 (961, 970, S, "", "Ibn ‘Ulayyah berkata tentang sesuatu yang ada di dalam hatinya itu:", ""),
 (971, 975, S, "", "Cinta kepada Allah dan nasihat kepada makhluk-Nya.", ""),
 (976, 983, S, "", "Inilah yang ada di dalam hatinya. Inilah yang ada.", ""),
 (984, 992, S, "", "Oleh itu, amalan hati lebih agung di sisi Allah daripada amalan badan.", ""),
 (993, 1000, S, "", "Amalan hati di sisi Allah lebih agung daripada amalan badan.", ""),
 (1001, 1015, S, "", "Antaranya nasihat. Adapun nasihat secara amali, ialah apa yang kami sebutkan tentang Jarir bin Abdullah رضي الله عنه.", ""),
 (1016, 1027, S, "", "Beliau membeli seekor kuda, lalu datang bersama pelayan yang menjual kuda itu untuk membayar harganya.", ""),
 (1028, 1039, S, "", "Apabila Jarir melihatnya, beliau berpendapat kuda itu bernilai lebih daripada yang dibayar, iaitu empat ratus.", ""),
 (1040, 1047, S, "", "Beliau bertanya: “Engkau rela menjualnya dengan empat ratus?” Dia menjawab: “Ya.”", ""),
 (1048, 1057, S, "", "Beliau berkata: “Tetapi kudamu ini bernilai lebih daripada itu.” Beliau menasihatinya.", ""),
 (1058, 1064, S, "", "Dia menjawab: “Terpulang kepada tuan.” Lalu beliau menambah seratus, dan lelaki itu bersetuju.", ""),
 (1065, 1069, S, "", "Beliau menambah seratus lagi, dan lelaki itu bersetuju.", ""),
 (1070, 1081, S, "", "Kemudian beliau menambah seratus lagi, dan seratus lagi, sehingga mencapai lapan ratus, dua kali ganda harga yang dijualnya.", ""),
 (1082, 1094, S, "", "Dia menjualnya empat ratus; beliau menambah empat ratus lagi, lalu berkata: “Ini harga kudamu.”", ""),
 (1095, 1106, S, "", "Kemudian beliau menoleh kepadanya dan berkata: “Aku tidak gila ketika membayar kamu empat ratus yang kedua.", ""),
 (1107, 1118, S, "", "Tetapi aku berbaiah dengan Rasulullah ﷺ untuk menasihati setiap Muslim.”", ""),
 (1119, 1129, S, "", "Akhlak ini sudah hilang daripada kita, kecuali pada segelintir yang dirahmati Allah Tabaraka wa Ta‘ala.", ""),
 (1130, 1137, S, "", "Kini sebahagian Muslim menganggap perkara seperti ini sebagai “luqatah” (barang temuan),", ""),
 (1138, 1145, S, "", "dan perkara yang dicemburui; orang ramai mencemburuinya kerana perbuatan itu.", ""),
 (1146, 1150, S, "", "Padahal pada hakikatnya ia satu pengkhianatan.", ""),
 (1151, 1160, S, "", "Kerana wajib atas seorang Muslim menyukai bagi saudaranya apa yang dia sukai. Wajib.", ""),
 (1161, 1170, H, LA_YU2MIN, LA_YU2MIN_MS, ""),
 (1171, 1181, S, "", "Apabila baginda bersabda “tidak beriman”, bermakna perkara ini besar, agung dan wajib:", ""),
 (1182, 1191, S, "", "seorang Muslim menyukai bagi saudaranya sesama Muslim apa yang dia sukai bagi dirinya. Dan termasuk di dalamnya nasihat.", ""),
 (1192, 1196, S, "", "Demikian juga termasuk nasihat kepada orang yang meminta pandangan anda.", ""),
 (1197, 1204, H, MUSTASHAR, "“Orang yang dimintai nasihat itu orang yang diamanahkan.” Nabi ﷺ bersabda:", ""),
 (1205, 1209, H, "«إِذَا اسْتَنْصَحَ أَحَدُكُمْ أَخَاهُ فَلْيَنْصَحْهُ»",
  "“Apabila salah seorang kamu meminta nasihat daripada saudaranya, hendaklah dia menasihatinya.”", ""),
 (1210, 1214, S, "", "Maksudnya, hendaklah dia memberitahunya apa yang dia tahu.", ""),
 (1215, 1225, S, "", "Terutama sekarang dalam urusan perkahwinan, perniagaan dan perkara-perkara lain.", ""),
 (1226, 1239, S, "", "Dia merasa perlu menyembunyikan sebahagian perkara daripadanya, katanya: aku tidak mahu mendedahkan keaiban lelaki itu, atau", ""),
 (1240, 1244, S, "", "aku tidak mahu begini — ini tidak boleh.", ""),
 (1245, 1252, S, "", "Jika dia bertanya dan meminta nasihat anda, anda wajib mengatakan kebenaran.", ""),
 (1253, 1264, S, "", "Adapun jika dia sekadar ingin tahu sahaja, maka anda tidak diwajibkan.", ""),
 (1265, 1272, S, "", "Tetapi jika dia hendak memasuki perniagaan bersamanya,", ""),
 (1273, 1276, S, "", "lalu bertanya anda, dan anda tahu dia —", ""),
 (1277, 1285, S, "", "apa kita hendak namakan dia ini? Saya katakan: pencuri.", ""),
 (1286, 1293, S, "", "Apa kita hendak namakan dia? Dia seorang pencuri. Baiklah, seorang pencuri.", ""),
 (1294, 1297, S, "", "Maka bagaimana anda tidak menasihatinya?", ""),
 (1298, 1308, S, "", "Anda wajib berkata: jangan bersekutu dengannya dalam perniagaan, dia tidak amanah.", ""),
 (1309, 1314, S, "", "Bukankah wajib anda katakan?", ""),
 (1315, 1324, S, "", "Ini bukan ghibah yang diharamkan, bahkan ghibah yang halal lagi wajib.", ""),
 (1325, 1328, S, "", "Kadang-kadang ghibah itu wajib.", ""),
 (1329, 1343, S, "", "Begitu juga jika seseorang meminta nasihat tentang lelaki yang melamar anak perempuannya, dan anda tahu sesuatu tentangnya, beritahulah.", ""),
 (1344, 1350, S, "", "Ini termasuk nasihat untuk agama Allah Tabaraka wa Ta‘ala.", ""),
 (1351, 1359, H, MUSTASHAR, "“Orang yang dimintai nasihat itu orang yang diamanahkan,” sebagaimana sabda Nabi ﷺ.", ""),
 (1360, 1369, S, "", "Ibn Taimiyyah: Telah sabit dalam Sahih bahawa Fatimah binti Qais", ""),
 (1370, 1378, S, "", "berkata kepada Nabi ﷺ: “Abu Jahm dan Muawiyah telah melamarku.”", ""),
 (1379, 1384, S, "", "Maka Nabi ﷺ menasihatinya.", ""),
 (1385, 1390, S, "", "Baginda bersabda: “Adapun Muawiyah, dia seorang sa‘luk” — iaitu miskin.", ""),
 (1391, 1402, S, "", "“Adapun Abu al-Jahm, tongkatnya tidak turun daripada keluarganya” — maksudnya dia suka memukul wanita.", ""),
 (1403, 1409, S, "", "Kemudian baginda bersabda: “Berkahwinlah dengan Usamah.” Lalu beliau berkahwin dengan Usamah.", ""),
 (1410, 1413, S, "", "Inilah nasihat kepada kaum Muslimin.", ""),
]
